package io.invenlio.procurement;
import java.util.*;import java.util.concurrent.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.testcontainers.service.connection.ServiceConnection;import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.test.context.ActiveProfiles;import org.springframework.test.web.servlet.MockMvc;import org.testcontainers.junit.jupiter.*;import org.testcontainers.postgresql.PostgreSQLContainer;import static org.junit.jupiter.api.Assertions.*;import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.jwt;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@Testcontainers@SpringBootTest@AutoConfigureMockMvc@ActiveProfiles("test")class ProcurementSecurityConcurrencyTest{static final UUID TA=UUID.fromString("11111111-1111-4111-8111-111111111111"),TB=UUID.fromString("22222222-2222-4222-8222-222222222222"),VA=UUID.randomUUID(),VB=UUID.randomUUID();@Container@ServiceConnection static final PostgreSQLContainer DB=new PostgreSQLContainer("postgres:17.6-alpine");@Autowired JdbcTemplate db;@Autowired MockMvc mvc;
 @BeforeEach void seed(){db.execute("TRUNCATE supplier_products,supplier_contacts,supplier_addresses,suppliers CASCADE");for(UUID tenant:List.of(TA,TB)){db.update("INSERT INTO organizations(id,name,slug,status,default_locale,default_timezone,default_currency,created_at,updated_at,version)VALUES(?,?,?,'ACTIVE','en','UTC','EUR',now(),now(),0) ON CONFLICT DO NOTHING",tenant,"Tenant "+tenant,tenant.toString());}UUID user=UUID.randomUUID();db.update("INSERT INTO user_identities(id,keycloak_subject,status,created_at,updated_at)VALUES(?,?,'ACTIVE',now(),now())",user,"buyer");for(UUID tenant:List.of(TA,TB)){UUID membership=UUID.randomUUID(),role=UUID.randomUUID();db.update("INSERT INTO organization_memberships(id,tenant_id,user_identity_id,status,created_at,updated_at,version)VALUES(?,?,?,'ACTIVE',now(),now(),0)",membership,tenant,user);db.update("INSERT INTO roles(id,tenant_id,name,system_role,created_at,updated_at,version)VALUES(?,?,?,false,now(),now(),0)",role,tenant,"PROC");for(String p:List.of("procurement-supplier:read","procurement-supplier:manage"))db.update("INSERT INTO role_permissions VALUES(?,?,?)",tenant,role,p);db.update("INSERT INTO membership_roles VALUES(?,?,?)",tenant,membership,role);}seedVariant(TA,VA,"A");seedVariant(TB,VB,"B");}
 @AfterEach void clean(){db.execute("TRUNCATE supplier_products,supplier_contacts,supplier_addresses,suppliers CASCADE");db.update("DELETE FROM catalog_product_variants WHERE id IN (?,?)",VA,VB);db.update("DELETE FROM catalog_products WHERE name IN ('PA','PB')");db.update("DELETE FROM audit_events WHERE tenant_id IN (?,?)",TA,TB);db.update("DELETE FROM membership_roles WHERE tenant_id IN (?,?)",TA,TB);db.update("DELETE FROM role_permissions WHERE tenant_id IN (?,?)",TA,TB);db.update("DELETE FROM organization_memberships WHERE tenant_id IN (?,?)",TA,TB);db.update("DELETE FROM roles WHERE tenant_id IN (?,?)",TA,TB);db.update("DELETE FROM user_identities WHERE keycloak_subject='buyer'");db.update("DELETE FROM organizations WHERE id IN (?,?)",TA,TB);}
 @Test void tenantACannotAccessTenantBGraphOrSku()throws Exception{UUID supplier=supplier(TB,"B-1"),address=UUID.randomUUID(),contact=UUID.randomUUID(),product=UUID.randomUUID();db.update("INSERT INTO supplier_addresses(id,tenant_id,supplier_id,type,address_line1,postal_code,city,country_code,is_primary,status,created_at,updated_at,version)VALUES(?,?,?,'ORDERING','B','1','B','DE',false,'ACTIVE',now(),now(),0)",address,TB,supplier);db.update("INSERT INTO supplier_contacts(id,tenant_id,supplier_id,first_name,last_name,email,role,is_primary,active,created_at,updated_at,version)VALUES(?,?,?,'B','C','b@example.test','ORDERING',false,true,now(),now(),0)",contact,TB,supplier);insertProduct(product,TB,supplier,VB,"B-SKU");mvc.perform(get("/api/v1/suppliers/"+supplier).with(token(TA))).andExpect(status().isNotFound());mvc.perform(get("/api/v1/supplier-addresses/"+address).with(token(TA))).andExpect(status().isNotFound());mvc.perform(get("/api/v1/supplier-contacts/"+contact).with(token(TA))).andExpect(status().isNotFound());mvc.perform(get("/api/v1/supplier-products/lookup?supplierId="+supplier+"&supplierSku=B-SKU").with(token(TA))).andExpect(status().isNotFound());UUID own=supplier(TA,"A-1");mvc.perform(post("/api/v1/suppliers/"+own+"/products").with(token(TA)).contentType("application/json").content(productJson(VB,"CROSS"))).andExpect(status().isBadRequest()).andExpect(jsonPath("$.code").value("INVALID_SUPPLIER_PRODUCT_VARIANT"));}
 @Test void concurrentPreferenceHasExactlyOneWinner()throws Exception{UUID s1=supplier(TA,"A-1"),s2=supplier(TA,"A-2"),p1=UUID.randomUUID(),p2=UUID.randomUUID();insertProduct(p1,TA,s1,VA,"SKU-1");insertProduct(p2,TA,s2,VA,"SKU-2");ExecutorService pool=Executors.newFixedThreadPool(2);try{CountDownLatch go=new CountDownLatch(1);Future<Integer>a=pool.submit(()->{go.await();return prefer(p1);});Future<Integer>b=pool.submit(()->{go.await();return prefer(p2);});go.countDown();Set<Integer>statuses=Set.of(a.get(),b.get());assertTrue(statuses.contains(200));assertTrue(statuses.contains(409));assertEquals(1,db.queryForObject("SELECT count(*) FROM supplier_products WHERE tenant_id=? AND variant_id=? AND preferred AND active",Integer.class,TA,VA));}finally{pool.shutdownNow();}}
 @Test void constraintsRejectInvalidCommercialValuesAndReassignment()throws Exception{UUID supplier=supplier(TA,"A-1"),other=supplier(TA,"A-2"),product=UUID.randomUUID();insertProduct(product,TA,supplier,VA,"SKU-1");assertThrows(Exception.class,()->db.update("UPDATE supplier_products SET supplier_id=? WHERE id=?",other,product));assertThrows(Exception.class,()->db.update("UPDATE supplier_products SET base_units_per_purchase_unit=0 WHERE id=?",product));assertThrows(Exception.class,()->db.update("UPDATE supplier_products SET order_multiple=0 WHERE id=?",product));}
 private void seedVariant(UUID t,UUID v,String suffix){UUID p=UUID.randomUUID();db.update("INSERT INTO catalog_products(id,tenant_id,name,status,base_unit,created_at,updated_at,version)VALUES(?,?,?,'ACTIVE','EA',now(),now(),0)",p,t,"P"+suffix);db.update("INSERT INTO catalog_product_variants(id,tenant_id,product_id,sku,normalized_sku,status,base_unit,option_signature,created_at,updated_at,version)VALUES(?,?,?,?,?,'ACTIVE','EA','DEFAULT',now(),now(),0)",v,t,p,"SKU-"+suffix,"SKU-"+suffix);}private UUID supplier(UUID t,String number){UUID id=UUID.randomUUID();db.update("INSERT INTO suppliers(id,tenant_id,supplier_number,normalized_supplier_number,name,status,default_currency,created_at,updated_at,version)VALUES(?,?,?,?,?,'ACTIVE','EUR',now(),now(),0)",id,t,number,number,number);return id;}private void insertProduct(UUID id,UUID t,UUID s,UUID v,String sku){db.update("INSERT INTO supplier_products(id,tenant_id,supplier_id,variant_id,supplier_sku,normalized_supplier_sku,purchase_unit_code,base_units_per_purchase_unit,currency,preferred,active,created_at,updated_at,version)VALUES(?,?,?,?,?,?,'EA',1,'EUR',false,true,now(),now(),0)",id,t,s,v,sku,sku);}private int prefer(UUID id)throws Exception{return mvc.perform(post("/api/v1/supplier-products/"+id+"/prefer").with(token(TA)).contentType("application/json").content("{\"version\":0}")).andReturn().getResponse().getStatus();}private String productJson(UUID variant,String sku){return "{\"variantId\":\""+variant+"\",\"supplierSku\":\""+sku+"\",\"purchaseUnitCode\":\"EA\",\"baseUnitsPerPurchaseUnit\":\"1\",\"currency\":\"EUR\",\"version\":0}";}private org.springframework.test.web.servlet.request.RequestPostProcessor token(UUID tenant){return jwt().jwt(j->j.subject("buyer").claim("tenant_id",tenant.toString()));}}
